<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useRoute} from 'vue-router'
import {usePayrollPage} from '../payrollPage'
import {WorkforceApiError} from '../api'
import {changeState} from '../payChanges'
import type {PayChange,ChangeWrite} from '../payChanges'
import type {Option} from '../types'
import type {PayrollHomeData,PayProfilePage,SalaryTemplate} from '../payrollTypes'
import type {TemplateLibraryEntry,TemplateAdoption} from '../payTemplatePublication'
import PhaseStatus from '../components/PhaseStatus.vue'
import PayChangeBulkActions from '../components/PayChangeBulkActions.vue'
import PayTemplateUpgrade from '../components/PayTemplateUpgrade.vue'
import PayChangeReview from '../components/PayChangeReview.vue'
import PayChangeEditor from '../components/PayChangeEditor.vue'
const {home,store,api,english,loading,busy,failure,notice,load,write}=usePayrollPage(),route=useRoute(),x=(z:string,e:string)=>english()?e:z
const companies=ref<Option[]>([]),salaryCompanies=ref<Option[]>([]),company=ref(String(route.query.companyId||'')),rows=ref<PayChange[]>([]),selected=ref<PayChange|null>(null),commands=new Map<string,string>()
const editing=ref(false),editRequest=ref<PayChange|null>(null),profiles=ref<PayProfilePage>({items:[],employees:[]}),templates=ref<SalaryTemplate[]>([]),adoptions=ref<TemplateAdoption[]>([]),scheduledDates=ref<Record<string,string>>({})
const month=ref(''),bulkKey=ref(0),bulkLocked=ref(false)
const salaryAccess=()=>salaryCompanies.value.some(c=>c.id===company.value)
function refresh(){if(bulkLocked.value)return;bulkKey.value++;selected.value=null;editing.value=false;return load(async()=>{let h:PayrollHomeData;try{h=await api().get<PayrollHomeData>('/payroll-home')}catch(e){if(!(e instanceof WorkforceApiError&&e.status===403&&home.value?.employeeManage))throw e;h={companies:[]} as unknown as PayrollHomeData}const options=[...h.companies];if(home.value?.employeeManage)for(const c of home.value.companies.filter(c=>home.value?.stores.some(s=>s.id===store.value&&s.companyId===c.id)))if(!options.some(o=>o.id===c.id))options.push(c);const c=options.find(c=>c.id===company.value)?.id||options[0]?.id||'';return {options,salary:h.companies,c,items:c?await api().get<PayChange[]>('/pay-change-requests?companyId='+c+(month.value?'&month='+month.value:'')):[]}},v=>{companies.value=v.options;salaryCompanies.value=v.salary;company.value=v.c;rows.value=v.items;selected.value=v.items.find(r=>r.id===route.query.requestId)||null})}
function begin(r:PayChange|null=null){if(!company.value)return;return load(async()=>{const [p,t,library]=await Promise.all([salaryAccess()?api().get<PayProfilePage>('/pay-profiles?companyId='+company.value):Promise.resolve({items:[],employees:[]}),salaryAccess()?api().get<SalaryTemplate[]>('/salary-templates?companyId='+company.value):Promise.resolve([]),home.value?.employeeManage?api().get<TemplateLibraryEntry[]>('/pay-template-library'):Promise.resolve([])]);const entries=Array.isArray(library)?library:[];return {p,t,a:entries.flatMap(e=>[...(e.adoption?[e.adoption]:[]),...(e.scheduledAdoptions||[]).map(s=>s.adoption)]).filter(a=>a.companyId===company.value),dates:Object.fromEntries(entries.flatMap(e=>(e.scheduledAdoptions||[]).map(s=>[s.adoption.id,s.effectiveDate])))}},v=>{profiles.value=v.p;templates.value=v.t;adoptions.value=v.a;scheduledDates.value=v.dates;editRequest.value=r;editing.value=true})}
function accept(updated:PayChange){selected.value=updated;const i=rows.value.findIndex(r=>r.id===updated.id);if(i<0)rows.value=[updated,...rows.value];else rows.value=rows.value.map(r=>r.id===updated.id?updated:r);if(updated.status==='stale'){notice.value='';failure.value=x('基线过期，未应用变更。','Baseline stale; changes were not applied.')+' '+(updated.staleReason||'')}}
function save(id:string,body:ChangeWrite){let updated:PayChange;return write(async()=>{updated=await api().put<PayChange>('/pay-change-requests/'+id,body)},()=>{editing.value=false;accept(updated)})}
function action(verb:string,note:string){const r=selected.value;if(!r)return;const key=[r.id,r.revision,r.hash,verb,note].join(':');let command=commands.get(key);if(!command){command=crypto.randomUUID();commands.set(key,command)}let updated:PayChange;return write(async()=>{updated=await api().put<PayChange>(`/pay-change-requests/${r.id}/actions`,{commandId:command,expectedRevision:r.revision,expectedHash:r.hash,action:verb,note})},()=>accept(updated))}
onMounted(()=>void refresh())
</script>
<template><section class="wf-panel"><header class="wf-toolbar"><h2>{{x('工资变更申请','Pay change requests')}}</h2><button :disabled="busy||loading||bulkLocked" @click="refresh">{{x('刷新','Refresh')}}</button><button :disabled="busy||loading||bulkLocked||!company" @click="begin()">{{x('新建申请','New request')}}</button></header><PhaseStatus :failure="failure" :notice="notice" :loading="loading"/><p>{{x('当前门店','Current store')}}: {{home?.stores.find(s=>s.id===store)?.name||store}}</p><label>{{x('公司','Company')}}<select v-model="company" :disabled="busy||loading||bulkLocked" @change="refresh"><option v-for="c in companies" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>{{x('筛选月份','Filter month')}}<input v-model="month" type="month" :disabled="busy||loading||bulkLocked" :aria-label="x('筛选月份','Filter month')" @change="refresh"></label><p v-if="!companies.length&&!loading&&!failure" role="alert">{{x('无工资或本店模板申请权限。','No pay or store template change access.')}}</p><PayTemplateUpgrade v-if="editing&&!loading&&editRequest?.content.upgrade" :request="editRequest" :adoptions="editRequest.content.adoption?[editRequest.content.adoption]:[]" :adoption-dates="scheduledDates" :target-version="editRequest.content.upgrade.targetRelease.version" @saved="editing=false;accept($event)" @close="editing=false"/><PayChangeEditor v-else-if="editing&&!loading" :key="editRequest?.id||'new'" :request="editRequest" :company-id="company" :salary-access="salaryAccess()" :employees="profiles.employees" :profiles="profiles.items" :birth-dates="profiles.employeeBirthDates||{}" :pr-documents="profiles.employeePrDocuments||{}" :templates="templates" :adoptions="adoptions" :scheduled-dates="scheduledDates" :busy="busy" @save="save" @cancel="editing=false"/><template v-else><p v-if="!rows.length&&!loading&&!failure" class="wf-empty">{{x('暂无变更申请。','No change requests.')}}</p><PayChangeBulkActions :disabled="busy||loading" :key="bulkKey" @locked="bulkLocked=$event" :rows="rows" :company-id="company" :month="month" :head-office="!!home?.headOffice" :salary-access="salaryAccess()" :template-access="!!home?.employeeManage" @updated="accept"><template #review="{request}"><button :disabled="busy||loading||bulkLocked" @click="selected=request">{{x('查看','Review')}}</button></template></PayChangeBulkActions><PayChangeReview v-if="selected&&!loading" :key="selected.id" :request="selected" :head-office="!!home?.headOffice&&(!!selected.adoptionId||salaryAccess())" :busy="busy||bulkLocked" @action="action" @edit="begin(selected)"/></template></section></template>
